sed -i 's/_userMessage.value = "Successfully generated dose schedule & scheduled $totalDosesScheduled notifications across Firebase!"/val missingMeds = itemsToSave.filter { !isMedicineInInventory(it.medicine) }.map { it.medicine }\n            val missingText = if (missingMeds.isNotEmpty()) "\\nWarning: Missing from inventory: ${missingMeds.joinToString()}" else ""\n            _userMessage.value = "Successfully generated dose schedule & scheduled $totalDosesScheduled notifications.$missingText"/' app/src/main/java/com/example/ui/viewmodel/MedicineViewModel.kt
